package com.medcore.backend.api.auditoria;import java.time.*;public record AuditoriaResponse(Long id,String usuario,String accion,String entidad,Long entidadId,String detalle,LocalDateTime fechaHora){public static AuditoriaResponse from(Auditoria a){return new AuditoriaResponse(a.getId(),a.getUsuario(),a.getAccion(),a.getEntidad(),a.getEntidadId(),a.getDetalle(),a.getFechaHora());}}
